create or replace function public.is_admin(_uid uuid) returns boolean language sql stable security definer set search_path='' as $$ select _uid=(select auth.uid()) and private.is_admin(); $$;
create or replace function public.has_role(_user_id uuid,_role text) returns boolean language sql stable security definer set search_path='' as $$ select _user_id=(select auth.uid()) and exists(select 1 from public.admin_roles where user_id=(select auth.uid()) and role=_role); $$;
create or replace function public.admin_stats() returns json language plpgsql stable security definer set search_path='' as $$ begin if not private.is_admin() then raise exception 'not allowed'; end if; return json_build_object('users',(select count(*) from public.profiles),'rooms',(select count(*) from public.rooms),'posts',(select count(*) from public.posts),'families',0,'open_reports',(select count(*) from public.admin_reports where status='open'),'gifts',(select count(*) from public.gifts),'coins',(select coalesce(sum(coins),0) from public.wallet_balances)); end; $$;
